BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create function pg_temp.i(n int)returns uuid language sql immutable as $$select('ee870000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table st(k text primary key,v jsonb);grant all on st,assertion_count to service_role;
insert into public.organizations(id,name)values(pg_temp.i(1),'Luma model SQL fixture'),(pg_temp.i(2),'Luma model other fixture');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)select pg_temp.i(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','luma-model-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp()from generate_series(101,103)n;
insert into public.profiles(id,org_id,role)select pg_temp.i(n),pg_temp.i(case when n=103 then 2 else 1 end),case when n=102 then'viewer'else'admin'end from generate_series(101,103)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role;
insert into public.properties(id,org_id,name)values(pg_temp.i(201),pg_temp.i(1),'Luma model SQL property'),(pg_temp.i(202),pg_temp.i(2),'Luma model other property');
insert into public.lumaleasing_config(id,property_id,api_key,is_active)values(pg_temp.i(301),pg_temp.i(201),'synthetic-model-key',true);
insert into public.conversations(id,property_id,channel)values(pg_temp.i(401),pg_temp.i(201),'widget');
create function pg_temp.claim(n int,body text default '{"messages":[{"role":"user","content":"Exact private request"}]}')returns jsonb language sql as $$select public.claim_recorded_luma_request(pg_temp.i(201),pg_temp.i(n),'chat',body,'synthetic-actor',encode(sha256(convert_to('synthetic-model-key','UTF8')),'hex'))$$;
create function pg_temp.model(n int,purpose text default'answer',params jsonb default'{"model":"fixture","messages":[{"role":"user","content":"Exact private prompt"}],"max_tokens":400}',lim bigint default 100000)returns jsonb language sql as $$select public.claim_luma_model(pg_temp.i(201),pg_temp.i(n),(select lease_token from public.luma_requests where property_id=pg_temp.i(201)and request_id=pg_temp.i(n)),purpose,params,jsonb_build_object('conversationId',pg_temp.i(401),'modeRevision',0),2000,lim)$$;
create function pg_temp.finish(n int,response jsonb default'{"content":"Actual saved response"}',status int default 200)returns boolean language sql as $$select public.finish_recorded_luma_request(pg_temp.i(201),pg_temp.i(n),(select lease_token from public.luma_requests where property_id=pg_temp.i(201)and request_id=pg_temp.i(n)),response,status)$$;
create function pg_temp.review(n int,target int,op text,actor int default 101)returns jsonb language sql as $$select public.review_luma_request(pg_temp.i(n),pg_temp.i(actor),pg_temp.i(201),pg_temp.i(target),jsonb_build_object('operation',op,'sourceHash',encode(sha256(convert_to(public.luma_request_source(pg_temp.i(201),pg_temp.i(target))::text,'UTF8')),'hex'),'reason','Exact retained evidence checked'))$$;
set local role service_role;
select pg_temp.check_it(pg_temp.claim(501)->>'state'='claimed','request claim retains original atomically');
select pg_temp.check_it((select raw_input::jsonb->'messages'->0->>'content'='Exact private request'from public.luma_request_inputs where request_id=pg_temp.i(501)),'exact raw input retained');
select pg_temp.check_it(pg_temp.claim(501)->>'state'='running','concurrent public request cannot reclaim');
select pg_temp.check_it(pg_temp.claim(501,'{"different":true}')->>'state'='conflict','raw identity conflict');
select pg_temp.check_it(pg_temp.model(501,'answer','{"model":"fixture"}',100)->>'state'='limited','allowance held before intent');
insert into st values('model',pg_temp.model(501));
select pg_temp.check_it((select v->>'state'='claimed'from st where k='model'),'one model claim');
select pg_temp.check_it(pg_temp.model(501)->>'state'='unknown','an intent with no result is never repeated');
select pg_temp.check_it(pg_temp.model(501,'answer','{"model":"changed"}')->>'state'='request_conflict','exact input cannot change');
select pg_temp.check_it((select used=2000 from public.luma_allowances where property_id=pg_temp.i(201)and bucket like'ai:%'),'replays do not reserve twice');
select pg_temp.check_it(public.finish_luma_model((select(v->>'id')::uuid from st where k='model'),pg_temp.i(201),pg_temp.i(501),pg_temp.i(900),'received','{"id":"actual","choices":[{"message":{"content":"Original provider answer"}}]}',null)->>'state'='not_found','wrong lease cannot attach provider output');
insert into st values('receipt',public.finish_luma_model((select(v->>'id')::uuid from st where k='model'),pg_temp.i(201),pg_temp.i(501),(select lease_token from public.luma_requests where request_id=pg_temp.i(501)),'received','{"id":"actual","choices":[{"message":{"content":"Original provider answer"}}],"usage":{"total_tokens":22}}',null));
select pg_temp.check_it((select v->>'state'='saved'and(v->>'usable')::boolean from st where k='receipt'),'actual model output retained and current authority checked');
select pg_temp.check_it(pg_temp.model(501)->'response'->>'id'='actual','exact saved model replay');
select pg_temp.check_it(public.finish_luma_model((select(v->>'id')::uuid from st where k='model'),pg_temp.i(201),pg_temp.i(501),(select lease_token from public.luma_requests where request_id=pg_temp.i(501)),'received','{"id":"different"}',null)->>'state'='request_conflict','original model result immutable');
select pg_temp.check_it(pg_temp.finish(501),'full handler result stored and completed');
select pg_temp.check_it(pg_temp.finish(501),'lost finish reply returns true after committed response');
select pg_temp.check_it(pg_temp.claim(501)->'response'->>'content'='Actual saved response','public completed retry replays full result');
select pg_temp.throws('select pg_temp.finish(501,''{"different":true}'')','different full result cannot overwrite');
select pg_temp.check_it(public.read_luma_request_evidence(pg_temp.i(103),pg_temp.i(201))->>'state'='forbidden','other property account cannot read private originals');
select pg_temp.check_it(public.read_luma_request_evidence(pg_temp.i(101),pg_temp.i(201),pg_temp.i(501))->'source'->'models'->0->'receipt'->'response'->'usage'->>'total_tokens'='22','operator reads actual reported usage');
select pg_temp.check_it(public.read_luma_request_evidence(pg_temp.i(101),pg_temp.i(201),pg_temp.i(501))::text not like'%synthetic-model-key%','read excludes widget credential');
select pg_temp.check_it(pg_temp.review(601,501,'retain_hold',102)->>'state'='forbidden','viewer cannot review');
select pg_temp.check_it(pg_temp.review(601,501,'retain_hold')->>'state'='saved','review attributed to current manager');
select pg_temp.check_it(public.read_luma_request_evidence(pg_temp.i(101),pg_temp.i(201),null,0,null,pg_temp.i(601))->>'operation'='retain_hold','lost review acknowledgement recoverable');
select pg_temp.check_it(pg_temp.claim(502)->>'state'='claimed','second admitted request');
update public.luma_requests set expires_at=now()-interval'1 minute'where request_id=pg_temp.i(502);
select pg_temp.check_it(not pg_temp.finish(502),'late full result retained without automatic completion');
select pg_temp.check_it((select count(*)=1 from public.luma_request_results where request_id=pg_temp.i(502)),'late original still retained');
select pg_temp.check_it(pg_temp.review(602,502,'release_saved_response')->>'state'='saved','manager releases exact complete saved response without repeating business work');
select pg_temp.check_it(pg_temp.claim(502)->'response'->>'content'='Actual saved response','released result available to same request');
select pg_temp.check_it(pg_temp.claim(503)->>'state'='claimed','third request');
select pg_temp.check_it(pg_temp.finish(503,'{"error":"handler failed"}',503),'actual failure retained');
select pg_temp.check_it(pg_temp.review(603,503,'release_saved_response')->>'state'='no_releasable_response','failure cannot be recast as completed');
select pg_temp.check_it(pg_temp.review(604,503,'cancel')->>'operation'='cancel','unused review cancellation saved');
select pg_temp.check_it(pg_temp.review(604,503,'retain_hold')->>'operation'='cancel','late original cannot bypass review cancellation');
select pg_temp.check_it(pg_temp.claim(504)->>'state'='claimed','fourth request');
insert into st values('late_model',pg_temp.model(504));
select set_config('p11.luma_conversation_scope',pg_temp.i(201)::text,true);
update public.conversations set is_human_mode=true,mode_revision=mode_revision+1 where id=pg_temp.i(401);
select pg_temp.check_it(public.finish_luma_model((select(v->>'id')::uuid from st where k='late_model'),pg_temp.i(201),pg_temp.i(504),(select lease_token from public.luma_requests where request_id=pg_temp.i(504)),'received','{"id":"late actual"}',null)->>'usable'='false','takeover holds late result but retains it');
select pg_temp.check_it(pg_temp.model(504)->>'state'='authority_changed','takeover blocks repeated model use');
select pg_temp.check_it((select response->>'id'='late actual'from public.luma_model_results where id=(select(v->>'id')::uuid from st where k='late_model')),'late actual response preserved');
select pg_temp.check_it(not has_table_privilege('authenticated','public.luma_model_results','SELECT'),'raw provider output private to server access');
select pg_temp.check_it(not has_function_privilege('authenticated','public.claim_luma_model(uuid,uuid,uuid,text,jsonb,jsonb,bigint,bigint)','EXECUTE'),'provider admission not browser-callable');
select pg_temp.throws('delete from public.luma_request_inputs where request_id=pg_temp.i(501)','original inputs immutable');
select pg_temp.check_it((select count(*)>0 and bool_and(actor_id is null and service_principal='lumaleasing.request_service'and not training_eligible and request::text not like'%private%'and result::text not like'%Original%')from public.shared_action_events where property_id=pg_temp.i(201)and action like'luma.request.%'and service_principal is not null),'actual service attribution and safe shared references with training off');
select pg_temp.check_it(pg_temp.claim(505)->>'state'='claimed','request for current-key boundary');
select set_config('p11.luma_widget_scope',pg_temp.i(201)::text,true);
update public.lumaleasing_config set api_key='replacement-synthetic-key'where property_id=pg_temp.i(201);
select pg_temp.check_it(not public.luma_request_authority(pg_temp.i(201),pg_temp.i(505),(select lease_token from public.luma_requests where request_id=pg_temp.i(505))),'replacement revokes prior request execution authority');
select pg_temp.check_it(not pg_temp.finish(505),'revoked request retains response without completion');
select pg_temp.check_it(pg_temp.review(605,505,'release_saved_response')->>'state'='authority_changed','manager cannot release response under replaced widget authority');
update public.lumaleasing_config set api_key='synthetic-model-key'where property_id=pg_temp.i(201);
create function pg_temp.reject_request_action()returns trigger language plpgsql as $$begin if new.property_id=pg_temp.i(201)and new.request->>'requestId'=pg_temp.i(550)::text then raise exception 'Fixture action failure';end if;return new;end$$;
reset role;create trigger model_fixture_action before insert on public.shared_action_events for each row execute function pg_temp.reject_request_action();set local role service_role;
select pg_temp.throws('select pg_temp.claim(550)','service evidence failure rolls back admission');
select pg_temp.check_it(not exists(select 1 from public.luma_requests where request_id=pg_temp.i(550))and not exists(select 1 from public.luma_request_inputs where request_id=pg_temp.i(550)),'no admitted request without original and action evidence');
reset role;drop trigger model_fixture_action on public.shared_action_events;set local role service_role;
reset role;
select 'Assertions passed: '||n from assertion_count;
ROLLBACK;
